mapper.select:
SELECT
WHERE t.deleted = 0
ORDER BY t.apply_time DESC, t.id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE volunteer_enrollment
status = 'cancelled', remark = #{remark}, updated_at = NOW()
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}

UPDATE volunteer_enrollment
SET status = #{toStatus}, updated_at = NOW()
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}

UPDATE volunteer_enrollment
project_id = #{e.projectId}, apply_time = #{e.applyTime}, status = #{e.status}, remark = #{e.remark}, updated_at = NOW()
WHERE id = #{e.id} AND deleted = 0 AND status = #{fromStatus}

mapper.select:
SELECT COUNT(*)
FROM volunteer_enrollment t
WHERE t.deleted = 0
AND t.project_id = #{projectId}
AND t.status = #{status}
